 svc_end:{rev:0,int:1,aud:"All staff",cap:["Workplace technology"],rto:24,rpo:24,life:"Maintain"},
 svc_int:{rev:0,int:1,aud:"Application teams",cap:["Integration","API management"],rto:8,rpo:1,life:"Invest"},
