 const r=rec||fb;let cis=t.cis||[];if(r){title=r.t||"";svc=svc||svcId(r.svc||r.service);ci=ci||r.ci;cis=cis.length?cis:(r.cis||[])}
 if(type==="ci"||(!svc&&!ci&&id)){const c=ciOf(id)||(svcOf(id)?null:null);if(c){ci=c.id;svc=svc||(c.scaled?c.svcI:c.svc)}else if(svcOf(id)){svc=svcOf(id).id;if(type==="ci")type="service"}}
