const peopleOpts=()=>people().map(p=>p.name);
const svcOpts=()=>SVCREG.map(s=>[s.id,s.n]);
function formNewSvc(){openForm({id:"s360_newsvc",title:"New service",story:"Adds a service to the portfolio and the CMDB service map. It starts at maturity 1 and shows up in impact analysis as soon as you link what it depends on.",submit:"Create service",
 fields:[{section:"Identity"},{k:"n",label:"Service name",type:"text",req:true,ph:"For example, Standards translation",help:"Use the name customers would say."},{k:"layer",label:"What kind of service",type:"chips",opts:["Business service","Technology service"],help:"Business services are what customers use; technology services support them (CSDM)."},{k:"tier",label:"Tier",type:"chips",opts:["Tier 1","Tier 2","Tier 3"]},{section:"People and money"},{k:"owner",label:"Service owner",type:"people",req:true},{k:"po",label:"Process owner",type:"people"},{k:"users",label:"Expected users",type:"number",min:1},{k:"cost",label:"Run cost a month",type:"money"},{k:"tgt",label:"Availability target (%)",type:"number",min:90,max:100,step:.01},{section:"Mapping"},{k:"obj",label:"Strategic objective",type:"select",opts:OBJS(),req:true},{k:"deps",label:"Depends on",type:"multi",opts:svcOpts()},{k:"offs",label:"Offerings (one per line)",type:"longtext",ph:"Standard\nPremium",ai:{label:"Suggest",fn:v=>"Standard\nExpedited"}}],
 defaults:{layer:"Business service",tier:"Tier 2",users:50,cost:5000,tgt:99.5,obj:OBJS()[0]},
 live:v=>`<p class="story">${H(v.n||"The service")} will be a <b>${H(v.layer||"")}</b> (${H(v.tier||"")}) with a ${v.tgt||99.5}% target, so its error budget is about <b>${Math.round((100-(v.tgt||99.5))/100*730*60)} minutes a month</b>. It depends on ${(v.deps||[]).length} services.</p>`,
 onSubmit:v=>{if(SVCREG.some(s=>s.n.toLowerCase()===String(v.n).toLowerCase())){toast("A service with that name already exists","warn");return}const id="svc_"+slug(v.n);SVCREG.push({id,n:v.n,tier:v.tier||"Tier 2",owner:v.owner,processOwner:v.po||v.owner,sme:[],users:+v.users||1,avail:+v.tgt||99.5,tgt:+v.tgt||99.5,cost:+v.cost||0,obj:[v.obj],proj:[],maturity:1,offerings:String(v.offs||"").split(/\n/).map(x=>x.trim()).filter(Boolean),deps:(v.deps||[]).slice()});LAYER[id]=v.layer==="Technology service"?1:2;audit("created service",v.n);toast("Service created: "+v.n,"good");closeDrawer();S.svc360.sel=id;S.v.s360d=0;render()}})}
function formNewOff(svc){openForm({id:"s360_newoff",title:"New service offering",story:"Offerings are what people actually order. This one will appear on the service, in the catalog and in cost transparency, with its own unit cost and approval rule.",submit:"Create offering",
 fields:[{k:"svc",label:"Service",type:"select",opts:svcOpts(),req:true},{k:"n",label:"Offering name",type:"text",req:true,ph:"For example, Translation review"},{k:"subs",label:"Sub-offerings (one per line)",type:"longtext",ph:"Standard\nExpedited"},{section:"Cost and service level"},{k:"unit",label:"Unit of consumption",type:"text",ph:"per user per month",req:true,help:"What one unit of this offering is, for unit costing."},{k:"price",label:"Cost per unit",type:"money"},{k:"sla",label:"Fulfillment target (hours)",type:"number",min:1},{section:"Approval"},{k:"thr",label:"Needs the budget owner above this price",type:"money"},{k:"ap",label:"Extra approver",type:"select",opts:["None","Security","Service owner","Data steward"]},{k:"pub",label:"Publish to the Service catalog",type:"toggle"}],
 defaults:{svc:svc||SVCREG[0].id,unit:"per user per month",price:20,sla:24,thr:2000,ap:"None",pub:true},
 live:v=>{const s=svcOf(v.svc);return `<p class="story">A request for ${H(v.n||"this offering")} costs <b>$${+v.price||0}</b> ${H(v.unit||"")}. ${(+v.price||0)>=(+v.thr||1e12)?"The budget owner has to approve it.":"Managers approve it; no budget owner is needed."} ${v.ap&&v.ap!=="None"?H(v.ap)+" also approves.":""} Fulfillment target ${+v.sla||0} hours on ${s?H(s.n):"the service"}.</p>`},
 onSubmit:v=>{const s=svcOf(v.svc);if(!s.offerings.includes(v.n))s.offerings.push(v.n);const o=mkOff(s,v.n,s.offerings.length-1);o.id="off_"+s.id+"_"+Date.now();o.subs=String(v.subs||"").split(/\n/).map(x=>x.trim()).filter(Boolean);if(!o.subs.length)o.subs=["Standard"];o.unit=v.unit;o.price=+v.price||0;o.sla=+v.sla||24;o.req={pending:0,approved:0,deployed:0,decommissioned:0};o.recent=[];o.rules=[];if((+v.price||0)>=(+v.thr||1e12))o.rules.push(["Cost per request is "+D$(v.thr)+" or more","Budget owner approves"]);if(v.ap&&v.ap!=="None")o.rules.push(["Every request",v.ap+" approves"]);o.rules.push(["Decommission request","Service owner confirms"]);SV.off.push(o);audit("created offering",v.n+" on "+s.n);toast("Offering added to "+s.n,"good");closeDrawer();S.svc360.sel=s.id;S.v.s360d=7;render()}})}
function formAssign(svc){openForm({id:"s360_assign",title:"Assign stakeholders",story:"Adds a person, AI agent, contractor or managed provider to the service in a role. Service owners and process owners also show up in their Person 360 under everything assigned.",submit:"Assign",
 fields:[{k:"svc",label:"Service",type:"select",opts:svcOpts(),req:true},{k:"role",label:"Role",type:"chips",opts:RACI_ROLES.filter(r=>r!=="Business users")},{k:"name",label:"Person or team",type:"people",req:true,help:"Choose a person, AI agent, contractor or managed provider."},{k:"why",label:"Reason, if replacing someone",type:"text",show:v=>v.role==="Service owner"||v.role==="Process owner"}],
 defaults:{svc:svc||SVCREG[0].id,role:"Subject matter expert"},
 live:v=>{const w=v.name&&who(v.name);return `<p class="story">${H(v.name||"This person")}${w?` is ${kindPill(w.kind)}`:""} becomes <b>${H(v.role||"")}</b> for ${H(SVN(v.svc))}.${v.role==="Service owner"?" They become Accountable for changes, access and retirement.":""}</p>`},
 onSubmit:v=>{const s=svcOf(v.svc);const st=stake(s.id);if(v.role==="Service owner"){s.owner=v.name;st.find(x=>x.role==="Service owner").name=v.name}else if(v.role==="Process owner"){s.processOwner=v.name;st.find(x=>x.role==="Process owner").name=v.name}else{if(!st.some(x=>x.role===v.role&&x.name===v.name))st.push({role:v.role,name:v.name});if(v.role==="Subject matter expert"&&!s.sme.includes(v.name))s.sme.push(v.name)}audit("assigned stakeholder",v.name+" as "+v.role+" on "+s.n);toast(v.name+" is now "+v.role+" of "+s.n,"good");closeDrawer();render()}})}
function formRel(svc,pre){openForm({id:"s360_rel",title:"Link a project to a service",story:"Records how a project relates to a service. Using and impacting links feed change risk; deprecating links start the retirement plan; improving links feed the maturity target.",submit:"Link project",
 fields:[{k:"svc",label:"Service",type:"select",opts:svcOpts(),req:true},{k:"p",label:"Project or demand",type:"select",opts:PROJ.map(p=>[p.id,p.id+" "+p.n]).concat(DEMAND.map(d=>[d.id,d.id+" "+d.n])),req:true},{k:"rel",label:"Relationship",type:"chips",opts:[["using","Using it"],["impacting","Impacting it"],["improving","Improving it"],["deprecating","Deprecating it"]]},{k:"from",label:"From",type:"date"},{k:"to",label:"To",type:"date"},{k:"note",label:"What it does to the service",type:"longtext"}],
 defaults:Object.assign({svc:svc||SVCREG[0].id,p:"PR1",rel:"improving",from:"2026-10-12",to:"2027-03-31"},pre||{}),
 live:v=>`<p class="story"><b>${H(projShort(v.p||""))}</b> will be listed as <b>${H((RELS[v.rel]||["improving"])[0].toLowerCase())}</b> ${H(SVN(v.svc))} from ${v.from?mon(v.from):"now"} to ${v.to?mon(v.to):"open ended"}. ${v.rel==="deprecating"?"The service owner is asked for a retirement plan and a data retention decision.":v.rel==="impacting"?"Changes in that window get a higher risk score.":""}</p>`,
 onSubmit:v=>{if(v.from&&v.to&&v.to<v.from){toast("The end date is before the start date","warn");return}SV.rel.push({p:v.p,svc:v.svc,rel:v.rel||"using",from:v.from||"2026-10-12",to:v.to||"2027-03-31",note:v.note||""});audit("linked project to service",v.p+" "+v.rel+" "+SVN(v.svc));toast("Linked "+projShort(v.p)+" to "+SVN(v.svc),"good");closeDrawer();render()}})}
function formReq(id,kind){const o=offerings().find(x=>x.id===id);if(!o)return;const s=svcOf(o.svc);const dec=kind==="decom";
 openForm({id:"s360_req",title:(dec?"Decommission ":"Request ")+o.n,story:dec?"Starts decommissioning: the service owner confirms, licenses are reclaimed and the cost stops. It lowers the deployed count and may trigger a scale-down in Cost transparency.":"Creates a request that follows this offering's approval rules, then fulfillment against the "+o.sla+" hour target.",submit:dec?"Request decommissioning":"Submit request",
  fields:[{k:"sub",label:"Which one",type:"select",opts:o.subs},{k:"qty",label:"Quantity",type:"number",min:1},{k:"by",label:dec?"Requested by":"Requested for",type:"people"},{k:"why",label:"Reason",type:"longtext",req:true,ai:{label:"Draft",fn:()=>dec?"No longer needed after the project closes.":"Needed for the new reviewers who start in November."}},{k:"date",label:"Needed by",type:"date"}],
  defaults:{sub:o.subs[0],qty:1,by:s.owner},
  live:v=>{const tot=(+v.qty||1)*o.price;const ap=[];if(!dec){ap.push("Manager");if(tot>=400)ap.push("Budget owner")}else ap.push("Service owner");return `<p class="story">Cost ${D$(tot)} (${+v.qty||1} × $${o.price} ${H(o.unit)}). Approvals: <b>${ap.join(", ")}</b>. Fulfillment target ${o.sla} hours.</p>`},
  onSubmit:v=>{o.req.pending+=1;o.recent.unshift({id:"RITM00"+(11300+Math.floor(Math.random()*500)),sub:v.sub,by:v.by||s.owner,st:"Awaiting approval",date:"Oct 6",cost:Math.round((+v.qty||1)*o.price)});audit(dec?"requested decommissioning":"requested offering",o.n+" ("+v.sub+")");toast((dec?"Decommission":"Request")+" submitted: "+o.n,"good");closeDrawer();render()}})}

/* ================= events ================= */
document.addEventListener("click",e=>{let t;
 if(t=e.target.closest("[data-s360-open]")){closeDrawer();S.svc360.sel=t.dataset.s360Open;S.v.s360d=0;if(S.screen!=="svc_360")go("svc_360");else render();return}
 if(e.target.closest("[data-s360-back]")){S.svc360.sel=null;render();return}
 if(t=e.target.closest("[data-s360-imp]")){openImpact({type:"service",id:t.dataset.s360Imp});return}
 if(t=e.target.closest("[data-s360-node]")){const id=t.dataset.s360Node;if(/^(aud_|obj_)/.test(id))return;openImpact({type:kindOf(id)==="svc"?"service":"ci",id});return}
 if(e.target.closest("[data-s360-newsvc]")){formNewSvc();return}
 if(t=e.target.closest("[data-s360-newoff]")){formNewOff(t.dataset.s360Newoff||null);return}
 if(t=e.target.closest("[data-s360-assign]")){formAssign(t.dataset.s360Assign);return}
 if(t=e.target.closest("[data-s360-newrel]")){formRel(t.dataset.s360Newrel);return}
 if(t=e.target.closest("[data-s360-order]")){formReq(t.dataset.s360Order,"order");return}
 if(t=e.target.closest("[data-s360-decom]")){formReq(t.dataset.s360Decom,"decom");return}
 if(t=e.target.closest("[data-s360-tbm]")){if(t.dataset.s360Tbm)(S.tbm=S.tbm||{}).focus=t.dataset.s360Tbm;closeDrawer();goG("tbm_model");return}
 if(e.target.closest("[data-s360-mat]")){goG("exe_mat");return}
 if(e.target.closest("[data-s360-sla]")){goG("svc_sla");return}
 if(t=e.target.closest("[data-s360-proj]")){const id=t.dataset.s360Proj;goG("ppm_proj");return}
 if(t=e.target.closest("[data-s360-tgt]")){const s=svcOf(t.dataset.s360Tgt);openForm({id:"s360_tgt",title:"Set target maturity for "+s.n,story:"The target drives the maturity gap shown here and in Maturity models.",submit:"Set target",fields:[{k:"lv",label:"Target level",type:"chips",opts:[["1","1 Initial"],["2","2 Managed"],["3","3 Defined"],["4","4 Measured"],["5","5 Optimizing"]]}],defaults:{lv:String(Math.min(5,s.maturity+1))},onSubmit:v=>{(SV.target=SV.target||{})[s.id]=+v.lv;audit("set maturity target",s.n+" to "+v.lv);toast("Target set to level "+v.lv,"good");closeDrawer();render()}});return}
 if(t=e.target.closest("[data-s360-raci]")){const [id,i,j]=t.dataset.s360Raci.split(":");const rc=raci(id),o=["","R","A","C","I"];const cur=o.indexOf(rc[i][j]||"");rc[i][j]=o[(cur+1)%o.length];audit("changed RACI",SVN(id)+": "+RACI_ACT[i]+" / "+RACI_ROLES[j]+" = "+(rc[i][j]||"none"));render();return}});

/* drag a project between relationship columns */
